{
  "name": "萬物類象記憶助手",
  "description": "一個專注於中國玄學萬物類象記憶的輔助工具，提供閃卡、測驗與類象檢視系統，協助系統化記憶八卦、五行、天干地支等複雜關聯。"
}

export enum Category {
  DI_ZHI = '地支類象',
  XING_SU = '二十八星宿',
  SHEN_JIANG = '十二神將',
  BA_GUA = '八卦類象',
  LIU_QIN = '六親類象',
  CHANG_SHENG = '十二長生',
  TIAN_GAN = '天干類象',
  GUAN_XI = '作用關係',
  YAO_WEI = '爻位類象',
  SHEN_SHA = '神煞'
}

export interface Card {
  id: string;
  category: Category;
  front: string;
  back: string;
  mastered: boolean;
  lastReviewed?: number;
}

export enum AppMode {
  LEARN = 'LEARN',
  QUIZ = 'QUIZ',
  VIEW = 'VIEW'
}

export interface QuizQuestion {
  id: string;
  type: 'choice' | 'match';
  question: string;
  answer: string;
  options?: string[];
  category: Category;
}

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Category, Card, AppMode } from './types';
import { INITIAL_DATA } from './constants';
import FlashcardView from './components/FlashcardView';
import QuizView from './components/QuizView';
import ListView from './components/ListView';

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.LEARN);
  const [cards, setCards] = useState<Card[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [searchQuery, setSearchQuery] = useState('');

  // Initialization
  useEffect(() => {
    const saved = localStorage.getItem('manwu_cards');
    if (saved) {
      setCards(JSON.parse(saved));
    } else {
      const initial: Card[] = INITIAL_DATA.map((d, i) => ({
        ...d,
        id: `card-${i}`,
        mastered: false,
      }));
      setCards(initial);
      localStorage.setItem('manwu_cards', JSON.stringify(initial));
    }
  }, []);

  // Save to local storage
  useEffect(() => {
    if (cards.length > 0) {
      localStorage.setItem('manwu_cards', JSON.stringify(cards));
    }
  }, [cards]);

  const toggleMastered = useCallback((id: string) => {
    setCards(prev => prev.map(c => c.id === id ? { ...c, mastered: !c.mastered } : c));
  }, []);

  const filteredCards = useMemo(() => {
    return cards.filter(card => {
      const matchCategory = selectedCategory === 'ALL' || card.category === selectedCategory;
      const matchSearch = card.front.includes(searchQuery) || card.back.includes(searchQuery);
      return matchCategory && matchSearch;
    });
  }, [cards, selectedCategory, searchQuery]);

  const categories = Object.values(Category);

  const exportData = () => {
    const dataStr = JSON.stringify(cards);
    const dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr);
    const exportFileDefaultName = 'manwu_data.json';
    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  const importData = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (e) => {
        try {
          const content = JSON.parse(e.target?.result as string);
          setCards(content);
        } catch (err) {
          alert('導入失敗，請檢查文件格式');
        }
      };
      reader.readAsText(file);
    }
  };

  return (
    <div className="min-h-screen bg-[#f9f7f2] flex flex-col">
      {/* Header */}
      <header className="bg-stone-800 text-stone-100 shadow-lg p-4 sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row justify-between items-center gap-4">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-red-800 rounded-full flex items-center justify-center font-bold text-xl border-2 border-stone-200">
              萬
            </div>
            <h1 className="text-xl font-bold tracking-widest">萬物類象記憶助手</h1>
          </div>

          <nav className="flex bg-stone-700 rounded-lg p-1">
            <button 
              onClick={() => setMode(AppMode.LEARN)}
              className={`px-4 py-2 rounded-md transition-all ${mode === AppMode.LEARN ? 'bg-stone-100 text-stone-800 shadow' : 'text-stone-300 hover:text-white'}`}
            >
              學習
            </button>
            <button 
              onClick={() => setMode(AppMode.QUIZ)}
              className={`px-4 py-2 rounded-md transition-all ${mode === AppMode.QUIZ ? 'bg-stone-100 text-stone-800 shadow' : 'text-stone-300 hover:text-white'}`}
            >
              測驗
            </button>
            <button 
              onClick={() => setMode(AppMode.VIEW)}
              className={`px-4 py-2 rounded-md transition-all ${mode === AppMode.VIEW ? 'bg-stone-100 text-stone-800 shadow' : 'text-stone-300 hover:text-white'}`}
            >
              檢視
            </button>
          </nav>

          <div className="flex gap-2">
            <button onClick={exportData} className="text-xs text-stone-400 hover:text-white border border-stone-600 px-2 py-1 rounded">導出</button>
            <label className="text-xs text-stone-400 hover:text-white border border-stone-600 px-2 py-1 rounded cursor-pointer">
              導入
              <input type="file" onChange={importData} className="hidden" accept=".json" />
            </label>
          </div>
        </div>
      </header>

      {/* Toolbar / Filters */}
      <div className="bg-white border-b border-stone-200 p-4 sticky top-[72px] md:top-[72px] z-40">
        <div className="max-w-6xl mx-auto flex flex-col md:flex-row gap-4 items-center">
          <select 
            value={selectedCategory} 
            onChange={(e) => setSelectedCategory(e.target.value as any)}
            className="w-full md:w-48 p-2 border border-stone-300 rounded focus:ring-2 focus:ring-stone-400 outline-none"
          >
            <option value="ALL">全部類象</option>
            {categories.map(c => <option key={c} value={c}>{c}</option>)}
          </select>

          <div className="relative w-full">
            <input 
              type="text"
              placeholder="搜尋關鍵字（例如：乾、圓、官鬼）..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full p-2 pl-10 border border-stone-300 rounded focus:ring-2 focus:ring-stone-400 outline-none"
            />
            <span className="absolute left-3 top-2.5 text-stone-400">🔍</span>
          </div>

          <div className="flex shrink-0 gap-4 text-sm text-stone-500">
            <span>已掌握: {cards.filter(c => c.mastered).length} / {cards.length}</span>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <main className="flex-1 max-w-6xl mx-auto w-full p-4">
        {mode === AppMode.LEARN && (
          <FlashcardView 
            cards={filteredCards} 
            onToggleMastered={toggleMastered} 
          />
        )}
        {mode === AppMode.QUIZ && (
          <QuizView 
            cards={filteredCards.length > 0 ? filteredCards : cards} 
            category={selectedCategory}
          />
        )}
        {mode === AppMode.VIEW && (
          <ListView 
            cards={filteredCards} 
            onToggleMastered={toggleMastered} 
          />
        )}

        {filteredCards.length === 0 && mode !== AppMode.QUIZ && (
          <div className="text-center py-20 text-stone-400">
            <div className="text-6xl mb-4">📭</div>
            <p>找不到符合條件的卡片</p>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-stone-200 border-t border-stone-300 p-6 text-center text-stone-500 text-sm">
        <p>© 2024 萬物類象記憶助手 - 專注玄學高效記憶</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Card } from '../types';

interface FlashcardViewProps {
  cards: Card[];
  onToggleMastered: (id: string) => void;
}

const FlashcardView: React.FC<FlashcardViewProps> = ({ cards, onToggleMastered }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  useEffect(() => {
    setCurrentIndex(0);
    setIsFlipped(false);
  }, [cards]);

  if (cards.length === 0) return null;

  const currentCard = cards[currentIndex];

  const nextCard = () => {
    setIsFlipped(false);
    setTimeout(() => {
      setCurrentIndex((prev) => (prev + 1) % cards.length);
    }, 150);
  };

  const prevCard = () => {
    setIsFlipped(false);
    setTimeout(() => {
      setCurrentIndex((prev) => (prev - 1 + cards.length) % cards.length);
    }, 150);
  };

  return (
    <div className="flex flex-col items-center py-10 max-w-2xl mx-auto">
      <div className="mb-6 flex justify-between w-full text-stone-500 font-medium">
        <span>{currentCard.category}</span>
        <span>{currentIndex + 1} / {cards.length}</span>
      </div>

      <div 
        className="w-full aspect-[3/2] perspective-1000 cursor-pointer mb-10"
        onClick={() => setIsFlipped(!isFlipped)}
      >
        <div className={`relative w-full h-full transition-transform duration-500 preserve-3d shadow-xl rounded-2xl ${isFlipped ? 'rotate-y-180' : ''}`}>
          {/* Front */}
          <div className="absolute inset-0 bg-white backface-hidden rounded-2xl border-2 border-stone-200 flex flex-col items-center justify-center p-8 text-center">
            <span className="text-stone-400 text-sm mb-4 uppercase tracking-widest">正面 - 象首</span>
            <h2 className="text-6xl font-bold text-stone-800">{currentCard.front}</h2>
            <p className="mt-8 text-stone-400 animate-pulse text-sm">點擊翻面查看類象</p>
          </div>

          {/* Back */}
          <div className="absolute inset-0 bg-stone-50 rotate-y-180 backface-hidden rounded-2xl border-2 border-stone-200 flex flex-col items-center justify-center p-8 text-center overflow-auto">
            <span className="text-stone-400 text-sm mb-4 uppercase tracking-widest">反面 - 萬物類象</span>
            <div className="text-xl leading-relaxed text-stone-700 font-medium">
              {currentCard.back}
            </div>
            <div className="mt-8 pt-6 border-t border-stone-200 w-full flex justify-center">
               <button 
                 onClick={(e) => {
                   e.stopPropagation();
                   onToggleMastered(currentCard.id);
                 }}
                 className={`flex items-center gap-2 px-4 py-2 rounded-full transition-colors ${currentCard.mastered ? 'bg-green-100 text-green-700' : 'bg-stone-200 text-stone-600 hover:bg-stone-300'}`}
               >
                 {currentCard.mastered ? '✅ 已掌握' : '⚪ 標記為已掌握'}
               </button>
            </div>
          </div>
        </div>
      </div>

      <div className="flex gap-8 items-center">
        <button 
          onClick={prevCard}
          className="w-14 h-14 rounded-full bg-white shadow hover:bg-stone-100 text-2xl transition-all border border-stone-200 flex items-center justify-center"
        >
          ←
        </button>
        <div className="flex flex-col items-center">
          <button 
            onClick={() => setIsFlipped(!isFlipped)}
            className="px-8 py-3 bg-stone-800 text-white rounded-lg shadow-lg hover:bg-stone-700 transition-colors font-bold tracking-widest"
          >
            翻轉卡片
          </button>
          <span className="mt-2 text-xs text-stone-400">或點擊卡片</span>
        </div>
        <button 
          onClick={nextCard}
          className="w-14 h-14 rounded-full bg-white shadow hover:bg-stone-100 text-2xl transition-all border border-stone-200 flex items-center justify-center"
        >
          →
        </button>
      </div>

      <div className="mt-12 w-full bg-stone-200 h-1.5 rounded-full overflow-hidden">
        <div 
          className="bg-stone-600 h-full transition-all duration-500" 
          style={{ width: `${((currentIndex + 1) / cards.length) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

export default FlashcardView;

import React, { useState, useEffect, useMemo } from 'react';
import { Card, QuizQuestion, Category } from '../types';

interface QuizViewProps {
  cards: Card[];
  category: Category | 'ALL';
}

const QuizView: React.FC<QuizViewProps> = ({ cards, category }) => {
  const [isStarted, setIsStarted] = useState(false);
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [userAnswer, setUserAnswer] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);

  const startQuiz = () => {
    if (cards.length < 4) {
      alert('卡片數量不足，無法生成測驗');
      return;
    }

    // Generate questions
    const shuffled = [...cards].sort(() => Math.random() - 0.5);
    const selected = shuffled.slice(0, Math.min(10, cards.length));

    const newQuestions: QuizQuestion[] = selected.map(card => {
      // Create distractors
      const others = cards.filter(c => c.id !== card.id);
      const distractors = [...others].sort(() => Math.random() - 0.5).slice(0, 3).map(c => c.front);
      const options = [card.front, ...distractors].sort(() => Math.random() - 0.5);

      return {
        id: card.id,
        type: 'choice',
        question: `以下哪些類象屬於 "${card.front}"？\n\n類象描述：${card.back.substring(0, 50)}...`,
        answer: card.front,
        options,
        category: card.category
      };
    });

    setQuestions(newQuestions);
    setScore(0);
    setCurrentQuestionIndex(0);
    setShowResult(false);
    setIsStarted(true);
    setFeedback(null);
    setUserAnswer(null);
  };

  const handleAnswer = (option: string) => {
    if (feedback) return; // Prevent multiple clicks

    setUserAnswer(option);
    const isCorrect = option === questions[currentQuestionIndex].answer;
    setFeedback(isCorrect ? 'correct' : 'wrong');

    if (isCorrect) {
      setScore(prev => prev + 1);
    }
  };

  const nextQuestion = () => {
    if (currentQuestionIndex + 1 < questions.length) {
      setCurrentQuestionIndex(prev => prev + 1);
      setFeedback(null);
      setUserAnswer(null);
    } else {
      setShowResult(true);
    }
  };

  if (!isStarted) {
    return (
      <div className="flex flex-col items-center py-20 text-center">
        <h2 className="text-3xl font-bold mb-4 text-stone-800">類象達人測驗</h2>
        <p className="text-stone-500 mb-8 max-w-md">
          系統將從當前篩選的「{category === 'ALL' ? '全部類象' : category}」中隨機抽取 10 題，
          測試你對類象關聯的熟練程度。
        </p>
        <div className="bg-stone-100 p-6 rounded-xl border border-stone-200 mb-8 w-full max-w-sm">
          <div className="flex justify-between mb-2">
            <span>測驗題數：</span>
            <span className="font-bold">10 題</span>
          </div>
          <div className="flex justify-between mb-2">
            <span>測驗類別：</span>
            <span className="font-bold">{category === 'ALL' ? '全類別' : category}</span>
          </div>
          <div className="flex justify-between">
            <span>及格分數：</span>
            <span className="font-bold">60 分</span>
          </div>
        </div>
        <button 
          onClick={startQuiz}
          className="bg-stone-800 text-white px-10 py-4 rounded-xl font-bold text-lg hover:bg-stone-700 transition-all shadow-lg"
        >
          開始測驗
        </button>
      </div>
    );
  }

  if (showResult) {
    const finalScore = Math.round((score / questions.length) * 100);
    return (
      <div className="flex flex-col items-center py-20 text-center">
        <div className="text-8xl mb-6">
          {finalScore >= 80 ? '🏆' : finalScore >= 60 ? '👍' : '📖'}
        </div>
        <h2 className="text-4xl font-bold mb-2">測驗完成</h2>
        <p className="text-stone-500 mb-6">您的得分：<span className="text-3xl font-bold text-stone-800">{finalScore}</span></p>

        <div className="flex flex-col gap-4 w-full max-w-xs">
          <button 
            onClick={startQuiz}
            className="w-full bg-stone-800 text-white py-3 rounded-lg font-bold hover:bg-stone-700"
          >
            再次挑戰
          </button>
          <button 
            onClick={() => setIsStarted(false)}
            className="w-full border border-stone-300 py-3 rounded-lg font-bold text-stone-600 hover:bg-stone-50"
          >
            回到大廳
          </button>
        </div>
      </div>
    );
  }

  const currentQ = questions[currentQuestionIndex];

  return (
    <div className="max-w-3xl mx-auto py-10">
      <div className="flex justify-between items-center mb-8">
        <span className="bg-stone-200 text-stone-700 px-3 py-1 rounded-full text-sm font-bold">
          {currentQ.category}
        </span>
        <span className="text-stone-400 font-medium">
          進度: {currentQuestionIndex + 1} / {questions.length}
        </span>
      </div>

      <div className="bg-white p-10 rounded-2xl shadow-sm border border-stone-200 mb-8">
        <h3 className="text-xl text-stone-800 leading-relaxed mb-10 font-medium whitespace-pre-wrap">
          {currentQ.question}
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          {currentQ.options?.map((option, idx) => (
            <button
              key={idx}
              onClick={() => handleAnswer(option)}
              disabled={!!feedback}
              className={`p-4 text-left rounded-xl border-2 transition-all font-bold text-lg
                ${feedback === null ? 'border-stone-200 hover:border-stone-400 hover:bg-stone-50' : 
                  option === currentQ.answer ? 'border-green-500 bg-green-50 text-green-700' : 
                  option === userAnswer ? 'border-red-500 bg-red-50 text-red-700' : 'border-stone-100 opacity-50'}
              `}
            >
              <span className="mr-3 text-stone-400">{String.fromCharCode(65 + idx)}.</span>
              {option}
            </button>
          ))}
        </div>
      </div>

      {feedback && (
        <div className="flex flex-col items-center animate-bounce-in">
          <div className={`text-xl font-bold mb-6 ${feedback === 'correct' ? 'text-green-600' : 'text-red-600'}`}>
            {feedback === 'correct' ? '✨ 回答正確！' : `❌ 回答錯誤，正確答案是：${currentQ.answer}`}
          </div>
          <button 
            onClick={nextQuestion}
            className="bg-stone-800 text-white px-12 py-3 rounded-lg font-bold hover:bg-stone-700 shadow-md"
          >
            {currentQuestionIndex + 1 === questions.length ? '查看結果' : '下一題'}
          </button>
        </div>
      )}
    </div>
  );
};

export default QuizView;

import React, { useMemo } from 'react';
import { Card, Category } from '../types';

interface ListViewProps {
  cards: Card[];
  onToggleMastered: (id: string) => void;
}

const ListView: React.FC<ListViewProps> = ({ cards, onToggleMastered }) => {
  const groupedCards = useMemo(() => {
    const groups: Record<string, Card[]> = {};
    cards.forEach(card => {
      if (!groups[card.category]) {
        groups[card.category] = [];
      }
      groups[card.category].push(card);
    });
    return groups;
  }, [cards]);

  return (
    <div className="space-y-10">
      {Object.entries(groupedCards).map(([category, catCards]) => (
        <section key={category}>
          <div className="flex items-center gap-4 mb-4 border-b-2 border-stone-800 pb-2">
            <h2 className="text-2xl font-bold text-stone-800">{category}</h2>
            <span className="text-stone-400 font-normal">({catCards.length} 項)</span>
          </div>

          <div className="grid grid-cols-1 gap-4">
            {catCards.map((card) => (
              <div 
                key={card.id} 
                className="bg-white p-4 rounded-lg shadow-sm border border-stone-200 hover:border-stone-400 transition-colors flex gap-6"
              >
                <div className="flex flex-col items-center justify-center min-w-[80px] border-r border-stone-100 pr-4">
                  <div className="text-3xl font-bold text-stone-900 mb-2">{card.front}</div>
                  <button 
                    onClick={() => onToggleMastered(card.id)}
                    className={`text-xs px-2 py-1 rounded transition-colors ${card.mastered ? 'bg-green-100 text-green-700' : 'bg-stone-100 text-stone-400 hover:text-stone-600'}`}
                  >
                    {card.mastered ? '已掌握' : '標記掌握'}
