                    className={`text-xs px-2 py-1 rounded transition-colors ${card.mastered ? 'bg-green-100 text-green-700' : 'bg-stone-100 text-stone-400 hover:text-stone-600'}`}
                  >
                    {card.mastered ? '已掌握' : '標記掌握'}
                  </button>
                </div>

                <div className="flex-1 flex items-center">
                  <p className="text-stone-600 leading-relaxed text-lg">
                    {card.back}
                  </p>
                </div>

                <div className="flex items-center gap-2">
                   {/* Simplified action buttons can be added here */}
                </div>
              </div>
            ))}
          </div>
        </section>
      ))}

      {Object.keys(groupedCards).length === 0 && (
         <div className="text-center py-20 text-stone-300 italic">
           選擇類別或關鍵字以開始檢視數據
         </div>
      )}
    </div>
  );
};

export default ListView;

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { Category, Card, AppMode } from './types';
import { INITIAL_DATA } from './constants';
import FlashcardView from './components/FlashcardView';
import QuizView from './components/QuizView';
import ListView from './components/ListView';

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>(AppMode.VIEW);
  const [cards, setCards] = useState<Card[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<Category | 'ALL'>('ALL');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const saved = localStorage.getItem('manwu_cards_v2');
    if (saved) {
      setCards(JSON.parse(saved));
    } else {
      const initial: Card[] = INITIAL_DATA.map((d, i) => ({
        ...d,
        id: `card-${i}`,
        mastered: false,
      }));
      setCards(initial);
      localStorage.setItem('manwu_cards_v2', JSON.stringify(initial));
    }
  }, []);

  useEffect(() => {
    if (cards.length > 0) {
      localStorage.setItem('manwu_cards_v2', JSON.stringify(cards));
    }
  }, [cards]);

  const toggleMastered = useCallback((id: string) => {
    setCards(prev => prev.map(c => c.id === id ? { ...c, mastered: !c.mastered } : c));
  }, []);

  const filteredCards = useMemo(() => {
    return cards.filter(card => {
      const matchCategory = selectedCategory === 'ALL' || card.category === selectedCategory;
      const matchSearch = card.front.includes(searchQuery) || card.back.includes(searchQuery);
      return matchCategory && matchSearch;
    });
  }, [cards, selectedCategory, searchQuery]);

  const categories = Object.values(Category);
  const catMap: Record<string, string> = {
    '地支類象': '地支',
    '八卦類象': '八卦',
    '天干類象': '天干',
    '十二神將': '神將',
