    '十二長生': '長生',
    '作用關係': '關係',
    '爻位類象': '爻位',
    '神煞': '神煞',
    '二十八星宿': '星宿'
  };

  return (
    <div className="min-h-screen bg-[#f7f5f0] text-stone-800 flex flex-col">
      {/* Header */}
      <header className="bg-white/80 backdrop-blur-md border-b border-stone-200 px-6 py-4 sticky top-0 z-50">
        <div className="max-w-6xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-stone-800 rounded-full flex items-center justify-center text-white font-bold text-xl">象</div>
            <div>
              <h1 className="text-xl font-bold">萬物類象記憶</h1>
              <p className="text-xs text-stone-400">系統化玄學類象訓練</p>
            </div>
          </div>

          <div className="flex bg-stone-100 rounded-xl p-1">
            <button 
              onClick={() => setMode(AppMode.VIEW)}
              className={`px-5 py-2 rounded-lg text-sm font-medium transition-all ${mode === AppMode.VIEW ? 'bg-white shadow-sm text-stone-900' : 'text-stone-500 hover:text-stone-700'}`}
            >檢視</button>
            <button 
              onClick={() => setMode(AppMode.LEARN)}
              className={`px-5 py-2 rounded-lg text-sm font-medium transition-all ${mode === AppMode.LEARN ? 'bg-white shadow-sm text-stone-900' : 'text-stone-500 hover:text-stone-700'}`}
            >學習</button>
            <button 
              onClick={() => setMode(AppMode.QUIZ)}
              className={`px-5 py-2 rounded-lg text-sm font-medium transition-all ${mode === AppMode.QUIZ ? 'bg-white shadow-sm text-stone-900 ring-1 ring-stone-900' : 'text-stone-500 hover:text-stone-700'}`}
            >測驗</button>
          </div>
        </div>
      </header>

      {/* Search & Categories */}
      <div className="max-w-6xl mx-auto w-full px-6 pt-8 space-y-6">
        {mode !== AppMode.QUIZ && (
          <div className="relative">
            <span className="absolute left-4 top-1/2 -translate-y-1/2 text-stone-400">🔍</span>
            <input 
              type="text"
              placeholder="搜尋名稱或類象..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full bg-white border border-stone-200 rounded-2xl py-4 pl-12 pr-4 focus:ring-2 focus:ring-stone-400 outline-none shadow-sm text-lg"
            />
          </div>
        )}

        <div className="flex flex-wrap gap-2 justify-center">
          <button 
            onClick={() => setSelectedCategory('ALL')}
            className={`px-4 py-2 rounded-full text-sm font-medium border transition-all ${selectedCategory === 'ALL' ? 'bg-stone-800 border-stone-800 text-white shadow-md' : 'bg-white border-stone-200 text-stone-600 hover:border-stone-400'}`}
          >全部</button>
          {categories.map(cat => (
            <button 
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-4 py-2 rounded-full text-sm font-medium border transition-all ${selectedCategory === cat ? 'bg-stone-800 border-stone-800 text-white shadow-md' : 'bg-white border-stone-200 text-stone-600 hover:border-stone-400'}`}
            >{catMap[cat] || cat}</button>
          ))}
        </div>
      </div>

      {/* Main Area */}
      <main className="flex-1 max-w-6xl mx-auto w-full p-6">
        {mode === AppMode.VIEW && <ListView cards={filteredCards} onToggleMastered={toggleMastered} />}
        {mode === AppMode.LEARN && <FlashcardView cards={filteredCards} onToggleMastered={toggleMastered} selectedCategory={selectedCategory} />}
        {mode === AppMode.QUIZ && <QuizView cards={filteredCards.length > 0 ? filteredCards : cards} category={selectedCategory} />}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { Card } from '../types';

interface ListViewProps {
  cards: Card[];
  onToggleMastered: (id: string) => void;
}

const ListView: React.FC<ListViewProps> = ({ cards, onToggleMastered }) => {
  const groupedCards = useMemo(() => {
    const groups: Record<string, Card[]> = {};
    cards.forEach(card => {
      if (!groups[card.category]) {
        groups[card.category] = [];
      }
      groups[card.category].push(card);
    });
    return groups;
  }, [cards]);

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pb-20">
      {(Object.entries(groupedCards) as [string, Card[]][]).map(([category, catCards]) => (
        catCards.map(card => (
          <div key={card.id} className="bg-white rounded-[2rem] p-8 border border-stone-100 shadow-sm flex flex-col h-full relative group">
            <div className="flex justify-between items-start mb-4">
              <span className="text-stone-400 text-sm font-medium">{category}</span>
              <button 
                onClick={() => onToggleMastered(card.id)}
                className={`w-6 h-6 rounded-full border flex items-center justify-center transition-all ${card.mastered ? 'bg-green-500 border-green-500 text-white' : 'border-stone-200 text-transparent hover:border-stone-400'}`}
              >✓</button>
            </div>

            <h3 className="text-4xl font-bold text-stone-900 mb-6">{card.front}</h3>

            <div className="flex flex-wrap gap-2">
              {card.back.split(/[，、；,;]/).filter(t => t.trim()).map((tag, i) => (
                <span 
                  key={i} 
                  className="px-3 py-1.5 bg-stone-50 text-stone-600 rounded-lg text-sm border border-stone-100"
                >
                  {tag.trim()}
                </span>
              ))}
            </div>
          </div>
        ))
      ))}
    </div>
  );
};

