import React, { useState, useEffect } from 'react';
import { Card, Category } from '../types';

interface FlashcardViewProps {
  cards: Card[];
  onToggleMastered: (id: string) => void;
  selectedCategory: Category | 'ALL';
}

const FlashcardView: React.FC<FlashcardViewProps> = ({ cards, onToggleMastered, selectedCategory }) => {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);

  useEffect(() => {
    setCurrentIndex(0);
    setIsFlipped(false);
  }, [cards, selectedCategory]);

  if (cards.length === 0) return null;

  const currentCard = cards[currentIndex];

  return (
    <div className="flex flex-col items-center py-6 max-w-4xl mx-auto">
      <div className="mb-6 flex justify-between w-full text-stone-400 text-sm font-medium px-4">
        <span>剩餘複習: {cards.length - currentIndex} 張</span>
        <span>分類: {currentCard.category}</span>
      </div>

      <div 
        className="w-full aspect-[4/3] max-h-[500px] perspective-1000 cursor-pointer mb-12"
        onClick={() => setIsFlipped(!isFlipped)}
      >
        <div className={`relative w-full h-full transition-transform duration-700 preserve-3d shadow-[0_20px_50px_rgba(0,0,0,0.05)] rounded-[3rem] ${isFlipped ? 'rotate-y-180' : ''}`}>
          {/* Front */}
          <div className="absolute inset-0 bg-white backface-hidden rounded-[3rem] flex flex-col items-center justify-center p-12 text-center">
            <h2 className="text-8xl font-bold text-stone-800 mb-8">{currentCard.front}</h2>
            <p className="text-stone-300 text-lg">點擊翻面</p>
          </div>

          {/* Back */}
          <div className="absolute inset-0 bg-white rotate-y-180 backface-hidden rounded-[3rem] flex flex-col items-center justify-center p-12 overflow-auto">
            <div className="flex flex-wrap gap-3 justify-center">
              {currentCard.back.split(/[，、；,;]/).filter(t => t.trim()).map((tag, i) => (
                <span key={i} className="px-5 py-3 bg-stone-50 text-stone-700 rounded-2xl text-xl font-medium border border-stone-100">
                  {tag.trim()}
                </span>
              ))}
            </div>
            <div className="mt-12 flex gap-4">
              <button 
                onClick={(e) => { e.stopPropagation(); onToggleMastered(currentCard.id); }}
                className={`px-6 py-2 rounded-full border transition-all ${currentCard.mastered ? 'bg-green-500 border-green-500 text-white' : 'border-stone-200 text-stone-400'}`}
              >已掌握</button>
            </div>
          </div>
        </div>
      </div>

      <div className="flex gap-6">
        <button 
          onClick={() => { setIsFlipped(false); setCurrentIndex((prev) => (prev - 1 + cards.length) % cards.length); }}
          className="w-16 h-16 rounded-full bg-white shadow-md hover:scale-105 transition-all flex items-center justify-center text-2xl"
        >←</button>
        <button 
          onClick={() => { setIsFlipped(false); setCurrentIndex((prev) => (prev + 1) % cards.length); }}
          className="w-16 h-16 rounded-full bg-stone-900 text-white shadow-lg hover:scale-105 transition-all flex items-center justify-center text-2xl"
        >→</button>
      </div>
    </div>
  );
};

export default FlashcardView;

import React, { useState } from 'react';
import { Card, QuizQuestion, Category } from '../types';

interface QuizViewProps {
  cards: Card[];
  category: Category | 'ALL';
}

const QuizView: React.FC<QuizViewProps> = ({ cards, category }) => {
  const [isStarted, setIsStarted] = useState(false);
  const [questions, setQuestions] = useState<QuizQuestion[]>([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [score, setScore] = useState(0);
  const [showResult, setShowResult] = useState(false);
  const [feedback, setFeedback] = useState<'correct' | 'wrong' | null>(null);

  const startQuiz = () => {
    const shuffled = [...cards].sort(() => Math.random() - 0.5);
    const selected = shuffled.slice(0, 10);
    const newQuestions: QuizQuestion[] = selected.map(card => {
      const distractors = cards.filter(c => c.id !== card.id).sort(() => Math.random() - 0.5).slice(0, 3).map(c => c.front);
      return {
        id: card.id,
        type: 'choice',
        question: card.back,
        answer: card.front,
        options: [card.front, ...distractors].sort(() => Math.random() - 0.5),
        category: card.category
      };
    });
    setQuestions(newQuestions);
    setScore(0);
    setCurrentIndex(0);
    setShowResult(false);
    setIsStarted(true);
    setFeedback(null);
  };

  const handleAnswer = (option: string) => {
    if (feedback) return;
    const isCorrect = option === questions[currentIndex].answer;
    setFeedback(isCorrect ? 'correct' : 'wrong');
    if (isCorrect) setScore(s => s + 1);
    setTimeout(() => {
      if (currentIndex + 1 < questions.length) {
        setCurrentIndex(i => i + 1);
        setFeedback(null);
      } else {
        setShowResult(true);
      }
    }, 1200);
  };

  if (!isStarted) {
    return (
      <div className="flex flex-col items-center py-20">
        <div className="bg-white rounded-[3rem] p-12 shadow-sm border border-stone-100 max-w-lg w-full text-center">
          <h2 className="text-3xl font-bold mb-6">準備好開始測驗嗎？</h2>
          <p className="text-stone-500 mb-10">將從目前選中的分類中抽選 10 題</p>
          <button onClick={startQuiz} className="w-full bg-stone-900 text-white py-5 rounded-2xl font-bold text-xl hover:scale-[1.02] transition-all">開始測驗</button>
        </div>
      </div>
    );
  }

  if (showResult) {
    return (
      <div className="flex flex-col items-center py-20 text-center">
        <div className="text-7xl mb-6">🎉</div>
        <h2 className="text-4xl font-bold mb-4">測驗結束</h2>
        <div className="bg-white rounded-[2rem] p-8 shadow-sm border border-stone-100 mb-8 w-64">
          <p className="text-stone-400 mb-1">您的得分</p>
          <p className="text-6xl font-black text-stone-900">{score * 10}</p>
        </div>
        <button onClick={() => setIsStarted(false)} className="bg-stone-900 text-white px-10 py-4 rounded-xl font-bold">回到檢視</button>
      </div>
    );
  }

  const q = questions[currentIndex];
  return (
    <div className="max-w-4xl mx-auto py-6">
      <div className="bg-white rounded-[2rem] p-6 mb-6 shadow-sm border border-stone-100 flex justify-between items-center">
        <span className="font-bold">測驗得分: {score} / {currentIndex}</span>
        <button onClick={() => setIsStarted(false)} className="text-stone-400 text-sm hover:text-stone-900">重置分數</button>
      </div>

      <div className="bg-white rounded-[3rem] p-12 shadow-sm border border-stone-100 mb-10 text-center">
        <p className="text-stone-400 text-sm mb-6 font-medium">以下類象屬於哪個項目？</p>
        <div className="flex flex-wrap gap-2 justify-center mb-10">
          {q.question.split(/[，、；,;]/).slice(0, 10).map((tag, i) => (
            <span key={i} className="px-4 py-2 bg-stone-50 rounded-xl border border-stone-100 text-stone-700 font-medium">
              {tag.trim()}
            </span>
          ))}
          {q.question.split(/[，、；,;]/).length > 10 && <span className="text-stone-300">...</span>}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {q.options?.map((opt, i) => (
          <button 
            key={i}
            onClick={() => handleAnswer(opt)}
            className={`py-8 bg-white border-2 rounded-[2rem] text-2xl font-bold transition-all
              ${feedback === null ? 'border-transparent hover:border-stone-800 shadow-sm' : 
                opt === q.answer ? 'border-green-500 bg-green-50 text-green-700' : 
                'border-red-100 bg-red-50 text-red-200'}
            `}
          >{opt}</button>
        ))}
      </div>
    </div>
  );
};

export default QuizView;
